import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/app.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY, username TEXT UNIQUE,
        email TEXT, role TEXT DEFAULT 'user',
        password_hash TEXT, api_key TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY, action TEXT,
        actor TEXT, target TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP)''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, password_hash) VALUES ('admin', 'admin@corp.internal', 'admin', 'redacted')")
    db.commit()
    db.close()

def verify_session(req):
    token = req.headers.get('X-Session-Token', '')
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 2:
        return None
    username, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), username.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return username
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    session_user = verify_session(request)
    if not session_user:
        return jsonify({'error': 'unauthorized'}), 401

    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Restrict searchable fields
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    if not value or len(value) > 100:
        return jsonify({'error': 'invalid query'}), 400

    # Build query with field validation but value interpolation
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
            ('user_search', session_user, f"{field}:{value}")
        )
        db.commit()
        return jsonify({'results': users, 'count': len(users)})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/users/<int:user_id>/profile', methods=['GET'])
def get_profile(user_id):
    session_user = verify_session(request)
    if not session_user:
        return jsonify({'error': 'unauthorized'}), 401
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
